#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>
#include <functional>

class ThreadPool {
private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> jobs;

    std::mutex queue_mutex; // Protects the job queue
    std::condition_variable cv; // The waiting room + bell
    bool shutdown = false; // The condition we care about

public:
    ThreadPool(size_t num_threads) {
        for (size_t i = 0; i < num_threads; ++i) {
            workers.emplace_back([this] {
                worker_loop(); // Each thread runs this
            });
        }
    }

    void submit(std::function<void()> job) {
        { // Scope for lock_guard
            std::lock_guard<std::mutex> lock(queue_mutex);
            jobs.push(std::move(job)); // 1. Make condition true
        } // lock released here
        cv.notify_one(); // 2. Wake one sleeping worker
    }

    ~ThreadPool() {
        {
            std::lock_guard<std::mutex> lock(queue_mutex);
            shutdown = true; // Signal we’re done
        }
        cv.notify_all(); // Wake ALL workers so they can exit
        for (auto& t : workers) t.join();
    }

private:
    void worker_loop() {
        while (true) {
            std::function<void()> job;

            { // Critical section
                std::unique_lock<std::mutex> lock(queue_mutex);

                // Wait until: we have a job OR we're shutting down
                cv.wait(lock, [this] {
                    return!jobs.empty() || shutdown;
                });

                // If shutting down and no jobs left, exit thread
                if (shutdown && jobs.empty()) return;

                job = std::move(jobs.front());
                jobs.pop();
            } // mutex unlocked here

            job(); // Run the job WITHOUT holding the lock
        }
    }
};

// Usage:
ThreadPool pool(8); // 8 worker threads, all sleeping initially

pool.submit([] { process_image("cat.jpg"); });
pool.submit([] { send_email("user@example.com"); });
// Workers wake up instantly, no polling, no wasted CPU
